$(document).ready(function () {

    //order-create.php -+
    alertify.set('notifier', 'position', 'top-right');
    alertify.set('notifier', 'position', 'top-right', 0);

    $(document).on('click', '.increment', function () {
        var $quantityInput = $(this).closest('.qtyBox').find('.qty');
        var productId = $(this).closest('.qtyBox').find('.prodId').val(); //val = getting value

        var currentValue = parseInt($quantityInput.val());

        if (!isNaN(currentValue)) {
            var qtyVal = currentValue + 1;
            $quantityInput.val(qtyVal);
            $quantityIncDec(productId, qtyVal);
        }
    });

    $(document).on('click', '.decrement', function () {
        var $quantityInput = $(this).closest('.qtyBox').find('.qty');
        var productId = $(this).closest('.qtyBox').find('.prodId').val();

        var currentValue = parseInt($quantityInput.val());

        if (!isNaN(currentValue) && currentValue > 1) {
            var qtyVal = currentValue - 1;
            $quantityInput.val(qtyVal);
            $quantityIncDec(productId, qtyVal);
        }
    });

    // update price function
    function $quantityIncDec(prodId, qty) {
        $.ajax({
            type: "POST",
            url: "orders-code.php",
            data: {
                'productIncDec': true,
                'product_Id': prodId,
                'quantity': qty
            },
            //alert success or error message
            success: function (response) {
                var res = JSON.parse(response);
                console.log(res);
                if (res.status == 200) {
                    $('#productArea').load(' #productContent')
                    alertify.success(res.message);
                } else {
                    alertify.error(res.message);
                }
            }
        });
    }

    //process place order button onclick 
    $(document).on('click', '.proceedToPlace', function () {
        //checking if you input select and number
        var cphone = $('#cphone').val();

        //this check if payment is null
        if (cphone == '' || !$.isNumeric(cphone)) {
            swal("Enter Phone Number", "Make sure Its a valid Phone No", "warning");
            return false;
        }

        var data = {
            'proceedToPlaceBtn': true,
            'cphone': cphone
        };

        $.ajax({
            type: "POST",
            url: "orders-code.php",
            data: data,
            success: function (response) {
                var res = JSON.parse(response);
                if (res.status == 200) {
                    window.location.href = "orders-summary"; //to proceed to place order
                } else if (res.status == 404) {
                    swal(res.message, res.message, res.status_type, {
                        buttons: {
                            catch: {
                                text: "Add Contractor",
                                value: "catch"
                            },
                            cancel: "Cancel"
                        }
                    })
                    .then((value) => {
                        switch (value) {
                            case "catch":
                                $('#c_phone').val(cphone);
                                $('#addCustomerModal').modal('show');
                                console.log('POP the Contractor add modal');
                                break;
                            default:
                        }
                    });
                } else {
                    swal(res.message, res.message, res.status_type);
                }
            }
        });
    });

    //Add customers from the table this section Order-create.php Modal positive
    $(document).on('click', '.saveCustomer', function () {
        var c_name = $('#c_name').val();
        var c_phone = $('#c_phone').val();
        var c_email = $('#c_email').val();

        if (c_name != '' && c_phone != '' && c_email != '') {
            if ($.isNumeric(c_phone)) {
                var data = {
                    'saveCustomerBtn': true,
                    'name': c_name,
                    'phone': c_phone,
                    'email': c_email,
                };

                $.ajax({
                    type: "POST",
                    url: "orders-code.php",
                    data: data,
                    success: function (response) {
                        var res = JSON.parse(response);

                        if (res.status == 200) {
                            swal(res.message, res.message, res.status_type);
                            $('#addCustomerModal').modal('hide');
                        } else if (res.status == 403) {
                            swal(res.message, res.message, res.status_type);
                        } else {
                            swal(res.message, res.message, res.status_type);
                        }
                    }
                });

            } else {
                swal("Enter valid phone number", "", "warning");
            }
        } else {
            swal("Please complete all required fields", "", "warning");
        }
    });

    //Orders-summary.php save receipt
    $(document).on('click', '#saveOrder', function () {
        swal({
            title: "Are you sure?",
            text: "Are you sure you want to withdraw these materials?",
            icon: "info",
            buttons: {
                confirm: {
                    text: "Yes",
                    value: true,
                    visible: true,
                    className: "btn btn-archive px-4", // Bootstrap success button style
                    closeModal: false // Do not close until the action completes
                },
                cancel: {
                    text: "No",
                    value: false,
                    visible: true,
                    className: "btn btn-danger px-4", // You can style it with Bootstrap classes
                    closeModal: true,
                }
            },
            closeOnClickOutside: false,
        }).then((willOrder) => {
            if (willOrder) {
                // Proceed with the AJAX call to save the order if confirmed
                $.ajax({
                    type: "POST",
                    url: "orders-code.php",
                    data: { 'saveOrder': true }, // Fetches order data
                    success: function (response) {
                        var res = JSON.parse(response);
                        if (res.status == 200) {
                            swal(res.message, res.message, res.status_type);

                            setTimeout(() => {
                                window.location.href = "order-create.php"; // Change this to your desired redirect page
                            }, 3000); // Adjust the timeout as necessary
                        } else {
                            swal(res.message, res.message, res.status_type);
                        }
                    }
                });
            } else {
                // Show a cancellation message if the user cancels the order
                swal("Order cancel", "Your order was not placed.", "info");
            }
        });
    });
});



function printMyBillingArea() {
    var divContents = document.getElementById("myBillingArea").innerHTML;
    var printWindow = window.open('', '', 'height=600,width=800');
    
    printWindow.document.write('<html><head><title> IMS ' + invoiceNumber + '</title>');
    printWindow.document.write('<style>body { font-family: fangsong; }</style>');
    printWindow.document.write('</head><body>');
    printWindow.document.write(divContents);
    printWindow.document.write('</body></html>');
    printWindow.document.close();
    printWindow.print();
}


window.jsPDF = window.jspdf.jsPDF;
var docPDF = new jsPDF();

function downloadPDF(invoiceNo) {
    var elementHTML = document.querySelector("#myBillingArea");
    docPDF.html(elementHTML, {
        callback: function () {
            docPDF.save(invoiceNo + '.pdf');
        },
        x: 10, // X position of content on the page 
        y: 5, // y position of content on the page
        width: 190, // Width of content
        windowWidth: 880 // Width of the content as seen in the browser
    });
}

function confirmDelete(url) {
    Swal.fire({
        title: 'Are you sure?',
        text: "You won't be able to revert this!",
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#0d6efd',
        cancelButtonColor: '#d33',
        confirmButtonText: 'Yes, Remove it!'
    }).then((result) => {
        if (result.isConfirmed) {
            Swal.fire({
                title: 'Remove!',
                text: 'successfully Remove it.',
                icon: 'success'
            }).then(() => {
                // Redirect to the delete URL
                window.location.href = url;
            });
        }
    });
}

